#include "supertux/physic.hpp"

#include "supertux/sector.hpp"

Physic::Physic() :
  ax(0), ay(0),
  vx(0), vy(0),
  gravity_enabled_flag(true),
  gravity_modifier(1.0f)
{
}

void
Physic::reset()
{
  ax = ay = vx = vy = 0;
  gravity_enabled_flag = true;
}

void
Physic::set_velocity(const Vector& vector)
{
  vx = vector.x;
  vy = vector.y;
}

void
Physic::set_acceleration(const Vector& vector)
{
  ax = vector.x;
  ay = vector.y;
}

Vector
Physic::get_movement(float dt_sec)
{
  float grav = gravity_enabled_flag ? (Sector::get().get_gravity() * gravity_modifier * 100.0f) : 0;

  // Semi-implicit Euler integration
  // with constant acceleration, this will result in a position delta of
  // v t + .5 a t (t+dt_sec) at total time t
  vx += ax * dt_sec;
  vy += (ay + grav) * dt_sec;
  Vector result(vx * dt_sec, vy * dt_sec);

  return result;
}

void
Coin::update(float dt_sec)
{
  // If we have a path to follow, follow it.
  if (get_walker()) {
    Vector v(0.0f, 0.0f);
    if (m_from_tilemap)
    {
      v = m_offset + get_walker()->get_pos(m_col.m_bbox.get_size(), m_path_handle);
    }
    else
    {
      get_walker()->update(dt_sec);
      v = get_walker()->get_pos(m_col.m_bbox.get_size(), m_path_handle);
    }

    if (get_path() && get_path()->is_valid()) {
      m_col.set_movement(v - get_pos());
    }
  }
}

